export interface ProjectStateData {
  meta: {
    productName: string;
    planVersion: string;
    repoVersion: string;
    lastUpdated: string;
    activeGate: 'A' | 'B' | 'C' | 'D';
    activeGateTitle: string;
    nextGateTitle: string;
    currentPhaseLabel: string;
    currentStepId: string;
    summaryFiveLines: string[];
  };
  gates: {
    id: 'A' | 'B' | 'C' | 'D';
    name: string;
    subtitle: string;
    status: GateStatus;
    approvalCommandHint: string;
  }[];
  currentStepCard: MicroStepCard;
  phases: PhaseItem[];
  proposedPhasesDraft: PhaseItem[];
  testLedger: TestLedgerEntry[];
  adrs: AdrEntry[];
  decisionMatrixPreview: {
    criterion: string;
    weightPct: number;
    status: string;
    notes: string;
  }[];
  performanceBudgets: PerformanceBudget[];
  crates: CrateNode[];
  featureCatalogSummary: {
    id: string;
    name: string;
    summary: string;
    status: 'Pendiente';
  }[];
  protocolContracts: ProtocolMessageContract[];
  secondaryContracts: {
    name: string;
    file: string;
    status: 'Propuesto (Pendiente)';
    snippet: string;
  }[];
  changelog: ChangelogEntry[];
  openRisks: RiskEntry[];
  repoFileTree: RepoFileNode[];
  discoveryQuestions: DiscoveryQuestion[];
  extraProposals: ExtraProposalItem[];
}

