  protocolContracts: [
    {
      msgType: 'hello',
      direction: 'Cliente → Daemon',
      version: 1,
      authRequired: true,
      maxFrameBytes: 16384,
      status: 'Propuesto (v1)',
      summary: 'Primer mensaje obligatorio del handshake en ws://127.0.0.1:47400/link (o vía Cloudflare Tunnel WSS) con token y rol.',
      exampleJson:
        '{"v":1,"id":"0192f1a0-1111-7000-8000-000000000001","msg":{"type":"hello","data":{"client":"miku_android","token":"<redacted>","capabilities":["agent_events","permission_decision"]}}}',
    },
    {
      msgType: 'hello_ack',
      direction: 'Daemon → Cliente',
      version: 1,
      authRequired: true,
      maxFrameBytes: 16384,
      status: 'Propuesto (v1)',
      summary: 'Confirmación de handshake exitoso con identificador de sesión y estado actual de la Island.',
      exampleJson:
        '{"v":1,"id":"0192f1a0-1111-7000-8000-000000000002","reply_to":"0192f1a0-1111-7000-8000-000000000001","msg":{"type":"hello_ack","data":{"session_id":"sess_01","island_state":"idle"}}}',
    },
    {
      msgType: 'ping',
      direction: 'Bidireccional',
      version: 1,
      authRequired: true,
      maxFrameBytes: 4096,
      status: 'Propuesto (v1)',
      summary: 'Solicitud de keepalive bajo demanda para enlaces LAN y Cloudflare Tunnel (9 tipos en miku-link v1).',
      exampleJson:
        '{"v":1,"id":"0192f1a0-1111-7000-8000-000000000003","msg":{"type":"ping","data":{"ts":1762315641}}}',
    },
    {
      msgType: 'pong',
      direction: 'Bidireccional',
      version: 1,
      authRequired: true,
      maxFrameBytes: 4096,
      status: 'Propuesto (v1)',
      summary: 'Respuesta de keepalive correlacionada por reply_to en miku-link v1.',
      exampleJson:
        '{"v":1,"id":"0192f1a0-1111-7000-8000-000000000009","reply_to":"0192f1a0-1111-7000-8000-000000000003","msg":{"type":"pong","data":{"ts":1762315641}}}',
    },
    {
      msgType: 'agent_event',
      direction: 'Bidireccional',
      version: 1,
      authRequired: true,
      maxFrameBytes: 65536,
      status: 'Propuesto (v1)',
      summary: 'Notificación de cambio de estado de un agente (Claude Code, Cursor, Antigravity, GitHub o propio).',
      exampleJson:
        '{"v":1,"id":"0192f1a0-1111-7000-8000-000000000004","msg":{"type":"agent_event","data":{"agent":"claude_code","kind":"needs_input","title":"Editar src/main.rs"}}}',
    },
    {
      msgType: 'permission_request',
      direction: 'Daemon → Cliente',
      version: 1,
      authRequired: true,
      maxFrameBytes: 65536,
      status: 'Propuesto (v1)',
      summary: 'Solicitud emitida por el Gatekeeper a la Island y Miku-Link con hash de solicitud exacta y TTL.',
      exampleJson:
        '{"v":1,"id":"0192f1a0-1111-7000-8000-000000000005","msg":{"type":"permission_request","data":{"req_hash":"sha256:9f86d08","agent":"claude_code","capability":"fs_write","target":"src/main.rs","ttl_sec":60,"pc_only":false}}}',
    },
    {
      msgType: 'permission_decision',
      direction: 'Cliente → Daemon',
      version: 1,
      authRequired: true,
      maxFrameBytes: 16384,
      status: 'Propuesto (v1)',
      summary: 'Decisión Y/N atada criptográficamente al req_hash exacto; en móvil exige biometría para Allow.',
      exampleJson:
        '{"v":1,"id":"0192f1a0-1111-7000-8000-000000000006","reply_to":"0192f1a0-1111-7000-8000-000000000005","msg":{"type":"permission_decision","data":{"req_hash":"sha256:9f86d08","decision":"allow","biometric_verified":true}}}',
    },
    {
      msgType: 'command',
      direction: 'Cliente → Daemon',
      version: 1,
      authRequired: true,
      maxFrameBytes: 65536,
      status: 'Propuesto (v1)',
      summary: 'Instrucción enviada desde la Island o el móvil hacia la cola serializada de una sesión.',
      exampleJson:
        '{"v":1,"id":"0192f1a0-1111-7000-8000-000000000007","msg":{"type":"command","data":{"session_id":"sess_01","action":"enqueue_prompt","text":"Ejecuta cargo test y corrige el warning"}}}',
    },
    {
      msgType: 'error',
      direction: 'Daemon → Cliente',
      version: 1,
      authRequired: false,
      maxFrameBytes: 16384,
      status: 'Propuesto (v1)',
      summary: 'Error tipado del protocolo (unsupported_version, unauthorized, frame_too_large, rate_limited, gatekeeper_denied).',
      exampleJson:
        '{"v":1,"id":"0192f1a0-1111-7000-8000-000000000008","reply_to":"0192f1a0-1111-7000-8000-000000000001","msg":{"type":"error","data":{"code":"unsupported_version","supported":[1]}}}',
    },
  ],

